"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["96251"],{6884(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>c,contentTitle:()=>h,toc:()=>p,assets:()=>d});var n=JSON.parse('{"id":"nhcx/v1/api/other/endpoints/other-internal-v1-task-on-submit","title":"Submit the task callback (internal variant) (adapter)","description":"Internal twin of /v1/task/on_submit (hcxOnTaskPostInternal): the payer Task bundle wrapping the ClaimResponse outcome of a reprocess or cancel.","source":"@site/docs/nhcx/v1/api/other/endpoints/other-internal-v1-task-on-submit.mdx","sourceDirName":"nhcx/v1/api/other/endpoints","slug":"/nhcx/v1/api/other/endpoints/other-internal-v1-task-on-submit","permalink":"/docs/main/docs/nhcx/v1/api/other/endpoints/other-internal-v1-task-on-submit","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Submit the task callback (internal variant) (adapter)","sidebar_label":"Submit the task callback (internal variant) (adapter)","sidebar_class_name":"api-method api-method--post","description":"Internal twin of /v1/task/on_submit (hcxOnTaskPostInternal): the payer Task bundle wrapping the ClaimResponse outcome of a reprocess or cancel.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-other.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Submit the task submit (internal variant) (adapter)","permalink":"/docs/main/docs/nhcx/v1/api/other/endpoints/other-internal-v1-task-submit"},"next":{"title":"Submit the notification subscribe","permalink":"/docs/main/docs/nhcx/v1/api/other/endpoints/other-v1-notification-subscribe"}}'),i=a(62540),r=a(43023),o=a(75064),s=JSON.parse('{"id":"other_internal_v1_task_on_submit","module":"Other","moduleId":"other","kind":"operation","method":"POST","path":"/internal/v1/task/on_submit","server":"https://apisbx.abdm.gov.in/hcx","servers":[{"url":"https://apisbx.abdm.gov.in/hcx","description":"Sandbox, NHCX exchange."},{"url":"https://apisprod.nha.gov.in/hcx","description":"Production."}],"summary":"Task callback (internal variant) (adapter)","title":"Submit the task callback (internal variant) (adapter)","description":"Internal twin of /v1/task/on_submit (hcxOnTaskPostInternal): the payer Task bundle wrapping the ClaimResponse outcome of a reprocess or cancel.\\n\\n### Business purpose\\n\\nThis is the internal-path form of the callback that closes a reprocess or cancellation. The OpenAPI lists it with the same description and bare object body as the public callback and distinguishes it only by the operationId suffix. Its role is unchanged: deliver the payer\'s final, auditable decision on an appeal, or confirmation of a preauth cancellation, in a Task bundle whose Task.output references a ClaimResponse that hospitals can parse with their normal adjudication logic.\\n\\n### When to use\\n\\nSame as the public callback: after acknowledging and re-adjudicating a Task, the payer posts a Task bundle with status completed and Task.output referencing the ClaimResponse, under the original correlation ID, with workflow 252, 253 or 254 (or PC02 for cancellation) and a responder status. The specifications do not say when the internal path is used in preference to the public one.\\n\\n### Preconditions\\n\\n- Inbound Task decrypted, correlation ID captured, 202 acceptance returned within 30 seconds.\\n- Registered payer with a valid Bearer token and the provider\'s certificate.\\n- Task bundle with Task.status completed and Task.output[0].valueReference resolving to a ClaimResponse entry in the bundle.\\n- Protected header echoing the request\'s correlation ID with a fresh API_call_ID, IST TIMESTAMP, outcome workflow ID and responder status.\\n- Confirmation that the internal route is the intended one.\\n\\n### Postconditions\\n\\nReturns 202 Accepted with the StatusSuccessResponse envelope, or 400, 404 or 500 in the same shape; the bundle is forwarded to the provider, which acknowledges within 30 seconds, extracts the ClaimResponse from Task.output and closes the appeal branch. The decision is final within the workflow context; approval leads to payment workflows 30, 31 and 33. No additional behaviour is documented for the internal variant.\\n\\n### Common mistakes\\n\\n- Expecting a different envelope or relaxed validation; none is documented.\\n- Sending a standalone ClaimResponse bundle rather than a Task wrapper, or minting a new correlation ID (NHCX-1010).\\n- Provider side: reading the ClaimResponse from Bundle.entry directly, or treating outcome complete as approval without checking the adjudication reason.\\n- Using an unconfigurable path that cannot switch between public and internal forms.\\n\\n### Best practices\\n\\n- Share the public callback\'s bundle builder; only the path differs.\\n- Acknowledge the inbound Task first, re-adjudicate asynchronously, then post.\\n- Provider: reuse the claim ClaimResponse parser, reached via Task.output[0].valueReference.reference.\\n- Idempotent handling on correlation ID; fresh API_call_ID and IST TIMESTAMP on the callback.\\n\\n### Related scenario\\n\\nA payer platform reviewing the taskhcxservice specification sees hcxOnTaskPost and hcxOnTaskPostInternal side by side. It implements a single outcome publisher that wraps the ClaimResponse in a Task bundle and posts to the public /v1/task/on_submit path unless configured for the internal one. When a hospital\'s cancellation Task for an unused preauth is processed, the publisher posts the Task bundle with PC02 semantics under the preauth\'s correlation ID; the hospital acknowledges within 30 seconds and raises a fresh preauth with a new case number for the revised treatment.\\n\\n### Specification\\n\\nChapter [Cancel, reprocess and shortfall](/docs/nhcx/v1/reference/fhir/cancel-reprocess-and-shortfall) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"},{"name":"x-hcx-sender_code","required":true,"description":"Your participant code. Mandatory on the envelope.","example":"1518@hcx","type":"string"},{"name":"x-hcx-recipient_code","required":true,"description":"The recipient\'s. For a provider, the processor code from the policy lookup. Mandatory on the envelope.","example":"1000004446@hcx","type":"string"},{"name":"x-hcx-api_call_id","required":true,"description":"Fresh on every message, including responses. Mandatory on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-request_id","required":false,"description":"One per originating request. The Open Protocol page marks it Mandatory; the Technical Specifications page marks it Optional. Optional on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-correlation_id","required":true,"description":"The thread. See the rule below. Mandatory on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-workflow_id","required":false,"description":"Which step, or which case. See the two readings below. Optional on the envelope.","example":"PC02","type":"string"},{"name":"x-hcx-timestamp","required":true,"description":"See the format note below. Mandatory on the envelope.","example":"<iso timestamp>","type":"string"},{"name":"x-hcx-status","required":true,"description":"Where this message stands. Values below. Mandatory on the envelope.","example":"response.complete","type":"string"},{"name":"x-hcx-ben-abha-id","required":true,"description":"The beneficiary\'s ABHA number. Mandatory on every exchange, including those with no beneficiary in the payload. Mandatory on the envelope.","example":"91711234567890","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"payload","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"payload":"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxNTE4QGhjeCJ9.encrypted_key.iv.ciphertext.tag"},"responses":[{"status":"200","description":"Returns 202 Accepted with the StatusSuccessResponse envelope, or 400, 404 or 500 in the same shape; the bundle is forwarded to the provider, which acknowledges within 30 seconds, extracts the ClaimResponse from Task.output and closes the appeal branch.","example":{"timestamp":"25/08/2026 11:05:00:448","api_call_id":"c5d6e7f8-a9b0-1234-8901-345678901234","correlation_id":"778899aa-bbcc-ddee-ff00-112233445566","result":{"sender_code":"1518@hcx","recipient_code":"1000004446@hcx","entity_type":"task","protocol_status":"request.queued"},"error":{"code":"","message":""}}}],"tag":"Other operations","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/internal/v1/task/on_submit \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'x-hcx-sender_code: 1518@hcx\' \\\\\\n  --header \'x-hcx-recipient_code: 1000004446@hcx\' \\\\\\n  --header \'x-hcx-api_call_id: <uuid>\' \\\\\\n  --header \'x-hcx-request_id: <uuid>\' \\\\\\n  --header \'x-hcx-correlation_id: <uuid>\' \\\\\\n  --header \'x-hcx-workflow_id: PC02\' \\\\\\n  --header \'x-hcx-timestamp: <iso timestamp>\' \\\\\\n  --header \'x-hcx-status: response.complete\' \\\\\\n  --header \'x-hcx-ben-abha-id: 91711234567890\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxNTE4QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/internal/v1/task/on_submit \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'x-hcx-sender_code: 1518@hcx\' \\\\\\n  --header \'x-hcx-recipient_code: 1000004446@hcx\' \\\\\\n  --header \'x-hcx-api_call_id: <uuid>\' \\\\\\n  --header \'x-hcx-request_id: <uuid>\' \\\\\\n  --header \'x-hcx-correlation_id: <uuid>\' \\\\\\n  --header \'x-hcx-workflow_id: PC02\' \\\\\\n  --header \'x-hcx-timestamp: <iso timestamp>\' \\\\\\n  --header \'x-hcx-status: response.complete\' \\\\\\n  --header \'x-hcx-ben-abha-id: 91711234567890\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxNTE4QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/hcx/internal/v1/task/on_submit\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"x-hcx-sender_code\\": \\"1518@hcx\\",\\n        \\"x-hcx-recipient_code\\": \\"1000004446@hcx\\",\\n        \\"x-hcx-api_call_id\\": \\"<uuid>\\",\\n        \\"x-hcx-request_id\\": \\"<uuid>\\",\\n        \\"x-hcx-correlation_id\\": \\"<uuid>\\",\\n        \\"x-hcx-workflow_id\\": \\"PC02\\",\\n        \\"x-hcx-timestamp\\": \\"<iso timestamp>\\",\\n        \\"x-hcx-status\\": \\"response.complete\\",\\n        \\"x-hcx-ben-abha-id\\": \\"91711234567890\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxNTE4QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/hcx/internal/v1/task/on_submit\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"x-hcx-sender_code\\": \\"1518@hcx\\",\\n    \\"x-hcx-recipient_code\\": \\"1000004446@hcx\\",\\n    \\"x-hcx-api_call_id\\": \\"<uuid>\\",\\n    \\"x-hcx-request_id\\": \\"<uuid>\\",\\n    \\"x-hcx-correlation_id\\": \\"<uuid>\\",\\n    \\"x-hcx-workflow_id\\": \\"PC02\\",\\n    \\"x-hcx-timestamp\\": \\"<iso timestamp>\\",\\n    \\"x-hcx-status\\": \\"response.complete\\",\\n    \\"x-hcx-ben-abha-id\\": \\"91711234567890\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxNTE4QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"Submit the task callback (internal variant) (adapter)",sidebar_label:"Submit the task callback (internal variant) (adapter)",sidebar_class_name:"api-method api-method--post",description:"Internal twin of /v1/task/on_submit (hcxOnTaskPostInternal): the payer Task bundle wrapping the ClaimResponse outcome of a reprocess or cancel.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-other.yaml",generated:!0},h,d={},p=[];function l(e){return(0,i.jsx)(o.A,{operation:s})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}}}]);